use super::*;
use crate::design::{TableOptionsDesign,TriggerDesign};
use crate::table_objects::{tokens,identifier,TokenKind};
fn equal<T:serde::Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).ok()==serde_json::to_value(b).ok()}
fn step(sql:String,label:impl Into<String>)->DesignStep{DesignStep{sql,label:label.into()}}
fn native(b:&Stored)->Result<&NativeMetadata>{b.native.as_ref().ok_or_else(||anyhow!("TABLE_NATIVE_METADATA_MISSING"))}
fn mysql_first_key(meta:&NativeMetadata,key:&str,column:&str)->Result<bool>{
    for row in &meta.indexes{
        if get(row,"Key_name")?==key&&get(row,"Seq_in_index")?.parse::<usize>()?==1{
            return Ok(opt(row,"Column_name")?.as_deref()==Some(column)
                &&get(row,"Index_type")?.eq_ignore_ascii_case("BTREE")&&opt(row,"Sub_part")?.is_none());
        }
    }
    Ok(false)
}
fn require_mysql_auto_keys(b:&Stored,d:&TableDesign)->Result<()>{
    let meta=native(b)?;let old=&b.public.design;
    for c in d.columns.iter().filter(|c|c.auto_increment){
        let original=c.orig_name.as_deref().unwrap_or(&c.name);
        let mut keyed=d.primary_key.first()==Some(&c.name);
        if keyed&&d.primary_key==old.primary_key{keyed=mysql_first_key(meta,"PRIMARY",original)?;}
        if !keyed{match &d.indexes{
            Some(indexes)=>{for index in indexes.iter().filter(|i|i.columns.first()==Some(&c.name)){
                let preserved=old.indexes.as_ref().is_some_and(|v|v.iter().any(|old|equal(old,index)));
                if !preserved||mysql_first_key(meta,&index.name,original)?{keyed=true;break;}
            }},
            None=>{for index in b.public.schema.indexes.iter().filter(|i|!i.primary){
                if mysql_first_key(meta,&index.name,original)?{keyed=true;break;}
            }}
        }}
        ensure!(keyed,"TABLE_MYSQL_AUTO_INCREMENT_KEY_UNPROVEN: 自增列必须是最终真实 BTREE 索引的首列，不从简化索引列表猜测表达式/前缀顺序");
    }
    Ok(())
}
fn mysql_modes(mode:&str)->Vec<&str>{let mut modes:Vec<_>=mode.split(',').filter(|s|!s.is_empty()&&*s!="NO_BACKSLASH_ESCAPES").collect();modes.sort_unstable();modes}
fn require_mysql_trigger_environment(trigger:&Record,table:&Record)->Result<()>{
    for (field,session) in [("charset","session_charset_client"),("collation","session_collation_connection")]{
        let original=get(trigger,field)?;let current=get(table,session)?;
        ensure!(!original.is_empty()&&!current.is_empty()&&original.eq_ignore_ascii_case(current),"TABLE_COPY_TRIGGER_CREATION_ENVIRONMENT_UNCERTIFIED: 原触发器的 {field} 与固定会话不同或为空，发送 DDL 前拒绝复制");
    }
    let original=get(trigger,"mode")?;let current=get(table,"session_sql_mode")?;
    ensure!(mysql_modes(original)==mysql_modes(current),"TABLE_COPY_TRIGGER_CREATION_MODE_UNCERTIFIED: 触发器创建模式与本次固定会话不一致");
    let no_backslash=|mode:&str|mode.split(',').any(|m|m=="NO_BACKSLASH_ESCAPES");
    ensure!(no_backslash(original)==no_backslash(current)||!get(trigger,"definition")?.contains('\\'),"TABLE_COPY_TRIGGER_SQL_MODE_UNCERTIFIED: 原触发器含反斜线且创建模式不同，不能证明字面量语义");
    Ok(())
}
fn verify_mysql_trigger_environment(original:&Record,actual:&Record)->Result<()>{
    let mut environment=Record::new();
    for (from,to) in [("charset","session_charset_client"),("collation","session_collation_connection"),("mode","session_sql_mode")]{environment.insert(to.into(),Some(get(actual,from)?.into()));}
    require_mysql_trigger_environment(original,&environment).map_err(|e|anyhow!("TABLE_COPY_TRIGGER_ENVIRONMENT_READBACK_MISMATCH: {e}"))
}
fn name(k:&DbKind,n:&str)->Result<String>{ensure!(!n.is_empty()&&n.len()<=if k.is_pg_family(){63}else{64}&&!n.contains('\0'),"TABLE_NATIVE_NAME_INVALID");Ok(db::quote_ident(k,n))}
fn safe_type(c:&design::ColumnDesign)->Result<()>{let ts=tokens(&c.data_type)?;let mut depth=0;for t in &ts{if t.symbol("("){depth+=1;}else if t.symbol(")"){depth-=1;ensure!(depth>=0,"TABLE_TYPE_UNBALANCED");}else if t.symbol(","){ensure!(depth>0,"TABLE_TYPE_TOP_LEVEL_COMMA");}else if t.kind==TokenKind::Word{ensure!(t.text.chars().all(|c|c.is_alphanumeric()||c=='_'||c=='.'),"TABLE_TYPE_TOKEN_INVALID");}}ensure!(depth==0,"TABLE_TYPE_UNBALANCED");let ts=tokens(&c.data_type)?;ensure!(!ts.is_empty()&&!ts.iter().any(|t|t.symbol(";")||["DEFAULT","CONSTRAINT","REFERENCES","CHECK","PRIMARY","GENERATED","COMMENT","COLLATE","NULL"].iter().any(|s|t.word(s))),"TABLE_COLUMN_TYPE_ESCAPE");for v in [&c.length,&c.scale].into_iter().flatten(){ensure!(!v.is_empty()&&v.bytes().all(|b|b.is_ascii_digit()),"TABLE_COLUMN_SIZE_INVALID");}Ok(())}
pub(super) fn lock_name(b:&Binding,table:&str)->String{format!("navkit_{}",&crate::object_catalog::revision(&(&b.fingerprint,&b.namespace,table))[..56])}
fn options(before:&TableOptionsDesign,w:Option<&TableOptionsDesign>,mysql:bool)->Result<TableOptionsDesign>{let mut o=before.clone();if let Some(w)=w{ensure!(w.strict.is_none()&&w.without_rowid.is_none(),"TABLE_OPTION_SQLITE_ONLY");if mysql{ensure!(w.engine.as_deref().map_or(true,|engine|engine.eq_ignore_ascii_case("InnoDB")),"TABLE_ENGINE_CHANGE_UNCERTIFIED: 当前原生身份与并发保护仅认证 InnoDB，发送 DDL 前拒绝更换引擎");ensure!(w.fillfactor.is_none(),"TABLE_OPTION_FILLFACTOR_PG_ONLY");for (slot,v) in [(&mut o.engine,&w.engine),(&mut o.charset,&w.charset),(&mut o.collation,&w.collation),(&mut o.row_format,&w.row_format)]{if let Some(v)=v{ensure!(!v.is_empty()&&v.bytes().all(|b|b.is_ascii_alphanumeric()||b==b'_'),"TABLE_OPTION_VALUE_INVALID");*slot=Some(v.clone());}}}else{ensure!(w.engine.is_none()&&w.charset.is_none()&&w.collation.is_none()&&w.row_format.is_none(),"TABLE_OPTION_MYSQL_ONLY");if let Some(v)=w.fillfactor{ensure!((10..=100).contains(&v),"TABLE_OPTION_FILLFACTOR_RANGE");o.fillfactor=Some(v);}}}Ok(o)}
fn trigger_sql(b:&Stored,t:&TriggerDesign)->Result<String>{
    let k=&b.kind;let full=db::qualified(k,&b.public.schema.database,&b.public.schema.table);let n=name(k,&t.name)?;
    if k.is_mysql_family(){let timing=t.timing.to_ascii_uppercase();let event=t.event.to_ascii_uppercase();ensure!(["BEFORE","AFTER"].contains(&timing.as_str())&&["INSERT","UPDATE","DELETE"].contains(&event.as_str()),"TABLE_TRIGGER_TIMING_EVENT_INVALID");let ts=tokens(&t.statement)?;ensure!(!ts.is_empty()&&t.statement.len()<=1024*1024,"TABLE_TRIGGER_BODY_INVALID");ensure!(!ts.iter().any(|t|["COMMIT","ROLLBACK","START","TRANSACTION","GRANT","REVOKE","DROP","ALTER","CREATE","PREPARE","EXECUTE","USE"].iter().any(|w|t.word(w))),"TABLE_TRIGGER_BODY_UNSAFE");Ok(format!("CREATE TRIGGER {} {timing} {event} ON {full} FOR EACH ROW {}",db::qualified(k,&b.public.schema.database,&t.name),t.statement.trim().trim_end_matches(';')))}else{
        // PG body 是已存在的触发器函数调用，禁止执行额外 SQL 或定义函数。
        let sql=t.statement.trim().trim_end_matches(';');let ts=tokens(sql)?;ensure!(ts.len()>8&&ts[0].word("CREATE")&&ts[1].word("TRIGGER")&&!ts.iter().any(|t|t.symbol(";")),"TABLE_PG_TRIGGER_DEFINITION_REQUIRED");ensure!(identifier(&ts[2])?==t.name,"TABLE_TRIGGER_NAME_MISMATCH");let on=ts.iter().position(|t|t.word("ON")).ok_or_else(||anyhow!("TABLE_TRIGGER_PARENT_UNKNOWN"))?;let (start,end)=qualified_span(sql,&ts,on+1)?;ensure!(source_reference(&sql[start..end],b),"TABLE_TRIGGER_PARENT_MISMATCH");ensure!(ts.iter().any(|t|t.word("FUNCTION")||t.word("PROCEDURE")),"TABLE_TRIGGER_FUNCTION_REQUIRED");let timing=ts.iter().skip(3).take(on.saturating_sub(3)).find(|t|t.word("BEFORE")||t.word("AFTER")||t.word("INSTEAD")).ok_or_else(||anyhow!("TABLE_TRIGGER_TIMING_UNKNOWN"))?;let event=ts.iter().skip(3).take(on.saturating_sub(3)).find(|t|t.word("INSERT")||t.word("UPDATE")||t.word("DELETE")||t.word("TRUNCATE")).ok_or_else(||anyhow!("TABLE_TRIGGER_EVENT_UNKNOWN"))?;ensure!(t.timing.eq_ignore_ascii_case(timing.text)&&t.event.eq_ignore_ascii_case(event.text),"TABLE_PG_TRIGGER_FIELDS_DEFINITION_MISMATCH: 时间/事件必须与完整 CREATE TRIGGER 定义一致");let _=n;Ok(sql.into())
    }
}
pub(super) fn design_steps(b:&Stored,d:&TableDesign)->Result<(Vec<DesignStep>,bool)>{
    let meta=native(b)?;let k=&b.kind;let mysql=k.is_mysql_family();let full=db::qualified(k,&d.schema,&d.table);ensure!(d.schema==b.public.schema.database&&d.table==b.public.schema.table,"TABLE_DESIGN_SCOPE_CHANGED");
    let old=&b.public.design;for c in &d.columns{name(k,&c.name)?;safe_type(c)?;if let Some(default)=&c.default_value{let ts=tokens(default)?;let mut depth=0;for t in ts{if t.symbol("("){depth+=1;}if t.symbol(")"){depth-=1;}ensure!(!(depth==0&&t.symbol(","))&&!t.symbol(";")&&!t.word("ALTER")&&!t.word("DROP")&&!t.word("CREATE"),"TABLE_DEFAULT_STATEMENT_ESCAPE");}ensure!(depth==0,"TABLE_DEFAULT_UNBALANCED");}if let Some(orig)=&c.orig_name{let original=old.columns.iter().find(|c|&c.name==orig).ok_or_else(||anyhow!("TABLE_COLUMN_ORIGIN_UNKNOWN"))?;if !equal(c,original){let raw=meta.columns.iter().find(|r|get(r,"name").ok()==Some(orig.as_str())).ok_or_else(||anyhow!("TABLE_COLUMN_METADATA_MISSING"))?;ensure!(!opt(raw,"generated")?.is_some_and(|v|!v.is_empty()),"TABLE_GENERATED_COLUMN_EDIT_UNSUPPORTED: 未修改定义完整保留");if mysql{let extra=get(raw,"extra")?.to_ascii_lowercase().replace("auto_increment","").replace("default_generated","");ensure!(extra.trim().is_empty(),"TABLE_COLUMN_UNMODELED_EXTRA: 此列修改会损失隐藏特征，已拒绝");}}}}
    if !mysql{
        if d.primary_key!=old.primary_key{for r in meta.constraints.iter().filter(|r|get(r,"kind").ok()==Some("p")){ensure!(get(r,"deferred")?=="false"&&get(r,"initially")?=="false","TABLE_DEFERRED_PRIMARY_KEY_EDIT_UNCERTIFIED");}}
        if let Some(target)=&d.foreign_keys{for f in target{if let Some(original)=old.foreign_keys.as_ref().and_then(|v|v.iter().find(|o|o.name==f.name)){if !equal(f,original){if let Some(r)=meta.constraints.iter().find(|r|get(r,"kind").ok()==Some("f")&&get(r,"name").ok()==Some(f.name.as_str())){ensure!(get(r,"deferred")?=="false"&&get(r,"initially")?=="false"&&get(r,"validated")?=="true"&&!get(r,"definition")?.contains("MATCH FULL"),"TABLE_FOREIGN_KEY_UNMODELED_FEATURE_EDIT: 原 FK 包含延迟/MATCH FULL/NOT VALID，未改定义会完整保留");}}}}}
        if let Some(target)=&d.checks{for c in target{if let Some(original)=old.checks.as_ref().and_then(|v|v.iter().find(|o|o.name==c.name)){if !equal(c,original){if let Some(r)=meta.constraints.iter().find(|r|get(r,"kind").ok()==Some("c")&&get(r,"name").ok()==Some(c.name.as_str())){ensure!(get(r,"validated")?=="true"&&get(r,"noinherit")?=="false","TABLE_CHECK_UNMODELED_FEATURE_EDIT: NOT VALID/NO INHERIT 检查修改未认证");}}}}}
        for c in &d.columns{if let Some(orig)=&c.orig_name{let original=old.columns.iter().find(|o|&o.name==orig).unwrap();if c.data_type!=original.data_type||c.length!=original.length||c.scale!=original.scale{let raw=meta.columns.iter().find(|r|get(r,"name").ok()==Some(orig)).ok_or_else(||anyhow!("TABLE_COLUMN_METADATA_MISSING"))?;ensure!(["0","100"].contains(&opt(raw,"collation")?.as_deref().unwrap_or("0")),"TABLE_NONDEFAULT_COLLATION_TYPE_EDIT_UNCERTIFIED: 非默认 collation 列类型修改需显式保全");}}}
    }
    if mysql{require_mysql_auto_keys(b,d)?;}
    let mut sanitized=workflow::strip_unchanged(d,old);sanitized.comment=d.comment.clone().filter(|v|Some(v)!=old.comment.as_ref());
    let identities:Vec<_>=if !mysql{d.columns.iter().filter(|c|c.orig_name.is_none()&&c.auto_increment).collect()}else{vec![]};
    for c in &identities{ensure!(["smallint","integer","int","bigint","int2","int4","int8"].contains(&c.data_type.to_ascii_lowercase().as_str())&&c.default_value.is_none(),"TABLE_NEW_IDENTITY_TYPE_DEFAULT_INVALID");if let Some(col)=sanitized.columns.iter_mut().find(|a|a.name==c.name){col.auto_increment=false;}}
    let mut steps=design::compile(k,&b.public.schema,&sanitized)?;
    for c in identities{steps.push(step(format!("ALTER TABLE {full} ALTER COLUMN {} ADD GENERATED BY DEFAULT AS IDENTITY",name(k,&c.name)?),format!("设置新列 {} 的独立 identity",c.name)));}
    if !mysql{let original:Vec<_>=old.columns.iter().filter(|c|d.columns.iter().any(|t|t.orig_name.as_deref()==Some(&c.name))).map(|c|c.name.as_str()).collect();let desired:Vec<_>=d.columns.iter().filter_map(|c|c.orig_name.as_deref()).collect();ensure!(original==desired,"TABLE_PG_COLUMN_REORDER_UNSUPPORTED: PostgreSQL 原生 ALTER 不支持列重排");let mut saw_added=false;for c in &d.columns{if c.orig_name.is_none(){saw_added=true;}else{ensure!(!saw_added,"TABLE_PG_COLUMN_INSERT_POSITION_UNSUPPORTED: 新列只能追加，不伪装改变物理顺序");}}}

    if mysql{for step in &mut steps{for c in &d.columns{let orig=c.orig_name.as_deref().unwrap_or(&c.name);let prefix=format!("ALTER TABLE {full} MODIFY COLUMN {} ",db::quote_ident(k,&c.name));let change=format!("ALTER TABLE {full} CHANGE COLUMN {} ",db::quote_ident(k,orig));if step.sql.starts_with(&prefix)||step.sql.starts_with(&change){let include_auto=tokens(&step.sql)?.iter().any(|token|token.word("AUTO_INCREMENT"));let mut def=design::column_definition(k,c,include_auto)?;if let Some(raw)=meta.columns.iter().find(|r|get(r,"name").ok()==Some(orig)){if let Some(col)=opt(raw,"collation")?{def.push_str(&format!(" COLLATE {}",name(k,&col)?));}}step.sql=if step.sql.starts_with(&change){format!("ALTER TABLE {full} CHANGE COLUMN {} {def}",db::quote_ident(k,orig))}else{format!("ALTER TABLE {full} MODIFY COLUMN {def}")};}}}}
    if let Some(checks)=&d.checks{let mut seen=std::collections::BTreeSet::new();for c in checks{name(k,&c.name)?;ensure!(seen.insert(&c.name),"TABLE_CHECK_DUPLICATE");crate::table_copy::expression(&c.expression)?;}
        for o in old.checks.as_ref().unwrap(){let wanted=checks.iter().find(|c|c.orig_name.as_deref()==Some(&o.name)||c.name==o.name);if !wanted.is_some_and(|w|equal(w,o)){steps.insert(0,step(format!("ALTER TABLE {full} DROP {} {}",if mysql{"CHECK"}else{"CONSTRAINT"},name(k,&o.name)?),format!("删除检查 {}",o.name)));}}
        for c in checks{if !old.checks.as_ref().unwrap().iter().any(|o|equal(o,c)){steps.push(step(format!("ALTER TABLE {full} ADD CONSTRAINT {} CHECK ({})",name(k,&c.name)?,c.expression),format!("保存检查 {}",c.name)));}}
    }
    if let Some(triggers)=&d.triggers{let mut seen=std::collections::BTreeSet::new();for t in triggers{ensure!(seen.insert(&t.name),"TABLE_TRIGGER_DUPLICATE");name(k,&t.name)?;}
        for o in old.triggers.as_ref().unwrap(){if !triggers.iter().any(|t|equal(t,o)){steps.insert(0,step(if mysql{format!("DROP TRIGGER {}",db::qualified(k,&d.schema,&o.name))}else{format!("DROP TRIGGER {} ON {full}",name(k,&o.name)? )},format!("删除触发器 {}",o.name)));}}
        for t in triggers{if !old.triggers.as_ref().unwrap().iter().any(|o|equal(o,t)){steps.push(step(trigger_sql(b,t)?,format!("保存触发器 {}",t.name)));if !mysql{let original_name=t.orig_name.as_deref().unwrap_or(&t.name);if let Some(r)=meta.triggers.iter().find(|r|get(r,"name").ok()==Some(original_name)){let mode=match get(r,"enabled")?{"O"=>"ENABLE","D"=>"DISABLE","R"=>"ENABLE REPLICA","A"=>"ENABLE ALWAYS",_=>return Err(anyhow!("TABLE_TRIGGER_ENABLE_UNKNOWN"))};steps.push(step(format!("ALTER TABLE {full} {mode} TRIGGER {}",name(k,&t.name)?),"保留触发器原有启用状态"));}}}}
    }
    let wanted=options(&b.public.options,d.options.as_ref(),mysql)?;if wanted!=b.public.options{if mysql{if wanted.charset!=b.public.options.charset{ensure!(wanted.collation!=b.public.options.collation,"TABLE_CHARSET_COLLATION_REQUIRED: 修改字符集时必须明确选择兼容的新 collation");}let mut attrs=Vec::new();for (n,v,old) in [("ENGINE",&wanted.engine,&b.public.options.engine),("DEFAULT CHARACTER SET",&wanted.charset,&b.public.options.charset),("COLLATE",&wanted.collation,&b.public.options.collation),("ROW_FORMAT",&wanted.row_format,&b.public.options.row_format)]{if v!=old{attrs.push(format!("{n}={}",v.as_deref().unwrap()));}}steps.push(step(format!("ALTER TABLE {full} {}",attrs.join(" ")),"保存真实表选项"));}else{steps.push(step(format!("ALTER TABLE {full} SET (fillfactor={})",wanted.fillfactor.unwrap()),"保存 fillfactor"));}}
    if mysql{let mut current:Vec<String>=old.columns.iter().filter_map(|o|d.columns.iter().find(|c|c.orig_name.as_deref()==Some(&o.name)).map(|c|c.name.clone())).collect();current.extend(d.columns.iter().filter(|c|c.orig_name.is_none()).map(|c|c.name.clone()));let desired:Vec<_>=d.columns.iter().map(|c|c.name.clone()).collect();if current!=desired{let (_,raw,_)=crate::table_copy::table_parts(&b.ddl)?;let renamed=d.columns.iter().any(|c|c.orig_name.as_ref().is_some_and(|o|o!=&c.name));for(i,c)in d.columns.iter().enumerate(){let unchanged=old.columns.iter().any(|o|equal(o,c));let definition=if unchanged{if renamed{let r=meta.columns.iter().find(|r|get(r,"name").ok()==Some(&c.name)).ok_or_else(||anyhow!("TABLE_COLUMN_METADATA_MISSING"))?;ensure!(!opt(r,"generated")?.is_some_and(|g|!g.is_empty()),"TABLE_REORDER_GENERATED_RENAME_UNCERTIFIED");}raw.iter().find(|part|tokens(part).ok().and_then(|ts|ts.first().and_then(|t|identifier(t).ok())).as_deref()==Some(c.name.as_str())).ok_or_else(||anyhow!("TABLE_REORDER_RAW_COLUMN_UNKNOWN"))?.clone()}else{let mut def=design::column_definition(k,c,true)?;if let Some(orig)=&c.orig_name{if let Some(r)=meta.columns.iter().find(|r|get(r,"name").ok()==Some(orig)){if let Some(coll)=opt(r,"collation")?{def.push_str(&format!(" COLLATE {}",name(k,&coll)?));}}}def};steps.push(step(format!("ALTER TABLE {full} MODIFY COLUMN {definition} {}",if i==0{"FIRST".into()}else{format!("AFTER {}",name(k,&d.columns[i-1].name)?)}),format!("保存字段 {} 的真实物理位置",c.name)));}}}
    // 全局索引名由服务端唯一性约束保护；禁止 IF NOT EXISTS 掩盖碰撞。
    Ok((steps,!equal(&d.columns,&old.columns)||d.primary_key!=old.primary_key))
}
fn generated_name(k:&DbKind,target:&str,old:&str)->String{let suffix=&crate::object_catalog::revision(&(target,old))[..16];let max=if k.is_pg_family(){40}else{41};let prefix: String=target.chars().scan(0usize,|n,c|{*n+=c.len_utf8();(*n<=max).then_some(c)}).collect();format!("{prefix}_{suffix}")}
fn qualified_span(sql:&str,ts:&[crate::table_objects::Token<'_>],i:usize)->Result<(usize,usize)>{let t=ts.get(i).ok_or_else(||anyhow!("TABLE_DDL_IDENTITY_MISSING"))?;identifier(t)?;let mut end=t.end;if let Some(dot)=ts.get(i+1){if dot.text=="."{let next=ts.get(i+2).ok_or_else(||anyhow!("TABLE_DDL_IDENTITY_MISSING"))?;identifier(next)?;end=next.end;}else if dot.text.starts_with('.') {return Err(anyhow!("TABLE_DDL_QUALIFIED_IDENTITY_UNCERTIFIED: {sql}"));}}Ok((t.start,end))}
fn source_reference(raw:&str,b:&Stored)->bool{
    let Ok(ts)=tokens(raw)else{return false};let mut parts=Vec::new();for t in ts{if t.text=="."{continue;}let Ok(n)=identifier(&t)else{return false};if t.kind==TokenKind::Word{parts.extend(n.split('.').map(str::to_string));}else{parts.push(n);}}
    parts==vec![b.public.schema.table.clone()]||parts==vec![b.public.schema.database.clone(),b.public.schema.table.clone()]
}
fn patch(sql:&str,mut edits:Vec<(usize,usize,String)>)->Result<String>{edits.sort_by_key(|e|e.0);ensure!(edits.windows(2).all(|e|e[0].1<=e[1].0),"TABLE_DDL_OVERLAPPING_EDITS");let mut out=String::new();let mut p=0;for(a,b,t)in edits{out.push_str(&sql[p..a]);out.push_str(&t);p=b;}out.push_str(&sql[p..]);Ok(out)}
fn rewrite_reference(sql:&str,b:&Stored,target:&str)->Result<String>{let ts=tokens(sql)?;let k=&b.kind;let mut edits=Vec::new();for (i,t) in ts.iter().enumerate(){if t.word("REFERENCES"){let (a,z)=qualified_span(sql,&ts,i+1)?;if source_reference(&sql[a..z],b){edits.push((a,z,db::qualified(k,&b.public.schema.database,target)));}}}patch(sql,edits)}
fn copy_trigger(sql:&str,b:&Stored,target:&str,new:&str)->Result<String>{let ts=tokens(sql)?;let tr=ts.iter().position(|t|t.word("TRIGGER")).ok_or_else(||anyhow!("TABLE_TRIGGER_HEADER_UNKNOWN"))?;let (a,z)=qualified_span(sql,&ts,tr+1)?;let on=ts.iter().enumerate().skip(tr+2).find(|(_,t)|t.word("ON")).map(|(i,_)|i).ok_or_else(||anyhow!("TABLE_TRIGGER_PARENT_UNKNOWN"))?;let (x,y)=qualified_span(sql,&ts,on+1)?;let mut edits=vec![(a,z,if b.kind.is_mysql_family(){db::qualified(&b.kind,&b.public.schema.database,new)}else{name(&b.kind,new)?}),(x,y,db::qualified(&b.kind,&b.public.schema.database,target))];
    // 仅改明确 DML 表引用，无法证明的同名 token 精准拒绝，字符串不改。
    for (i,t) in ts.iter().enumerate().skip(on+2){if t.start<y||t.kind==TokenKind::Literal{continue;}if ["INTO","UPDATE","FROM","JOIN"].iter().any(|w|t.word(w)){if ts.get(i+1).is_some(){let (a,z)=qualified_span(sql,&ts,i+1)?;if source_reference(&sql[a..z],b){edits.push((a,z,db::qualified(&b.kind,&b.public.schema.database,target)));}}}}
    patch(sql,edits)
}
pub(super) fn operation_steps(b:&Stored,o:&workflow::TableOperation)->Result<Vec<DesignStep>>{
    let meta=native(b)?;let k=&b.kind;let full=db::qualified(k,&o.schema,&o.table);if o.kind=="clear"{ensure!(o.target_table.is_none(),"TABLE_CLEAR_TARGET_FORBIDDEN");metadata::require_clear_visibility(k,&meta.table)?;return Ok(vec![step(format!("DELETE FROM {full}"),"清空表，保留真实结构")]);}
    ensure!(["copy_data","copy_structure"].contains(&o.kind.as_str()),"TABLE_OPERATION_UNSUPPORTED");let target=o.target_table.as_deref().ok_or_else(||anyhow!("TABLE_COPY_TARGET_REQUIRED"))?;name(k,target)?;ensure!(target!=o.table,"TABLE_COPY_TARGET_INVALID");let dest=db::qualified(k,&o.schema,target);let mut steps=Vec::new();
    if k.is_mysql_family(){
        ensure!(get(&meta.table,"engine")?.eq_ignore_ascii_case("InnoDB"),"TABLE_COPY_ENGINE_UNCERTIFIED: 只认证 InnoDB 数据锁和回执");
        let (prefix,parts,suffix)=crate::table_copy::table_parts(&b.ddl)?;let _=prefix;ensure!(!tokens(&suffix)?.iter().any(|t|["PARTITION","TABLESPACE","DATA","DIRECTORY","ENCRYPTION"].iter().any(|w|t.word(w))),"TABLE_COPY_MYSQL_SPECIAL_OPTIONS_UNCERTIFIED");
        let mut out=Vec::new();for p in parts{let ts=tokens(&p)?;let mut edits=Vec::new();if ts.first().is_some_and(|t|t.word("CONSTRAINT")){let old=identifier(&ts[1])?;edits.push((ts[1].start,ts[1].end,name(k,&generated_name(k,target,&old))?));}let p=patch(&p,edits)?;out.push(rewrite_reference(&p,b,target)?);}
        steps.push(step(format!("CREATE TABLE {dest} ({}{}",out.join(", "),suffix),"复制完整 SHOW CREATE 定义（含 FK/CHECK/generated/options/comment）"));
    }else{
        let t=&meta.table;ensure!(get(t,"replica")?=="d"&&get(t,"access_method")?=="heap"&&["p","u"].contains(&get(t,"persistence")?),"TABLE_COPY_PG_STORAGE_IDENTITY_UNCERTIFIED: 非默认 replica identity/自定义 table AM/TEMP 未认证");ensure!(get(t,"kind")?=="r"&&get(t,"inherits")?=="0"&&get(t,"rules")?=="0"&&get(t,"rls")?=="false"&&get(t,"force_rls")?=="false"&&get(t,"partition")?=="false","TABLE_COPY_PG_SPECIAL_RELATION_UNCERTIFIED: 分区/继承/RLS/规则需独立认证");
        ensure!(meta.constraints.iter().all(|r|get(r,"kind").ok()!=Some("x")),"TABLE_COPY_PG_EXCLUSION_UNCERTIFIED");
        ensure!(meta.columns.iter().all(|r|get(r,"typekind").ok()==Some("b")&&["int2","int4","int8","float4","float8","numeric","bool","text","varchar","bpchar","bytea","date","time","timetz","timestamp","timestamptz","interval","uuid","json","jsonb","bit","varbit"].contains(&get(r,"typename").unwrap_or(""))),"TABLE_COPY_PG_TYPE_UNCERTIFIED: 自定义/enum/domain/数组复制需要独立核验");
        ensure!(meta.indexes.iter().all(|r|get(r,"valid").ok()==Some("1")&&get(r,"ready").ok()==Some("1")),"TABLE_COPY_PG_INVALID_INDEX");
        ensure!(meta.triggers.iter().all(|r|get(r,"constraint").ok()==Some("0")),"TABLE_COPY_PG_CONSTRAINT_TRIGGER_UNCERTIFIED");
        for r in &meta.triggers{let definition=get(r,"function_definition")?;let ts=tokens(definition)?;ensure!(!ts.iter().any(|t|t.word("EXECUTE")),"TABLE_COPY_PG_DYNAMIC_TRIGGER_FUNCTION_UNCERTIFIED: 动态 SQL 函数无法证明不会改写源表");for (i,t)in ts.iter().enumerate(){if ["INTO","UPDATE","FROM","JOIN"].iter().any(|w|t.word(w))&&ts.get(i+1).is_some(){let(a,z)=qualified_span(definition,&ts,i+1)?;ensure!(!source_reference(&definition[a..z],b),"TABLE_COPY_PG_TRIGGER_FUNCTION_SOURCE_REFERENCE: 函数固定引用源表，需独立复制函数后再认证");}}}

        steps.push(step(format!("CREATE {}TABLE {dest} (LIKE {full} INCLUDING ALL)",if get(t,"persistence")?=="u"{"UNLOGGED "}else{""}),"复制完整 PostgreSQL LIKE INCLUDING ALL 定义"));
        for seq in &meta.sequences{if get(seq,"identity")?.is_empty(){let column=get(seq,"column")?;let new=generated_name(k,target,&format!("{column}_seq"));let sq=db::qualified(k,&o.schema,&new);steps.push(step(format!("CREATE SEQUENCE {sq} AS {} INCREMENT BY {} MINVALUE {} MAXVALUE {} START WITH {} CACHE {} {}",get(seq,"type")?,get(seq,"increment")?,get(seq,"min")?,get(seq,"max")?,get(seq,"start")?,get(seq,"cache")?,if get(seq,"cycle")?=="true"{"CYCLE"}else{"NO CYCLE"}),"创建独立 owned serial 序列"));steps.push(step(format!("ALTER SEQUENCE {sq} OWNED BY {dest}.{}",name(k,column)?),"绑定复制列序列所有权"));steps.push(step(format!("ALTER TABLE {dest} ALTER COLUMN {} SET DEFAULT nextval({}::regclass)",name(k,column)?,db::quote_literal(&sq)),"替换 serial 源序列共享默认值"));}}
        for r in &meta.constraints{if get(r,"kind")?=="f"{let def=rewrite_reference(get(r,"definition")?,b,target)?;steps.push(step(format!("ALTER TABLE {dest} ADD CONSTRAINT {} {def}",name(k,&generated_name(k,target,get(r,"name")?))?),"复制外键（包括正确的自引用）"));}}
        if let Some(c)=&b.public.schema.comment{steps.push(step(format!("COMMENT ON TABLE {dest} IS {}",db::quote_literal(c)),"复制表注释"));}
        // LIKE INCLUDING ALL 保留列注释；表空间和非 fillfactor reloptions 单独精准拒绝。
        ensure!(get(t,"tablespace")?=="0","TABLE_COPY_PG_TABLESPACE_UNCERTIFIED");if let Some(raw)=opt(t,"options")?{for attr in raw.trim_matches(['{','}']).split(',').filter(|s|!s.is_empty()){ensure!(attr.starts_with("fillfactor="),"TABLE_COPY_PG_RELOPTION_UNCERTIFIED: {attr}");}if let Some(v)=b.public.options.fillfactor{steps.push(step(format!("ALTER TABLE {dest} SET (fillfactor={v})"),"复制真实 fillfactor"));}}
    }
    if o.kind=="copy_data"{let cols=meta.columns.iter().filter_map(|r|match opt(r,"generated"){Ok(None)=>Some(Ok(r)),Ok(Some(g))if g.is_empty()=>Some(Ok(r)),Ok(_)=>None,Err(e)=>Some(Err(e))}).collect::<Result<Vec<_>>>()?;let cols=cols.iter().map(|r|name(k,get(r,"name")?)).collect::<Result<Vec<_>>>()?.join(",");ensure!(!cols.is_empty(),"TABLE_COPY_NO_INSERTABLE_COLUMNS");steps.push(step(format!("INSERT INTO {dest} ({cols}) {}SELECT {cols} FROM {full}",if k.is_pg_family(){"OVERRIDING SYSTEM VALUE "}else{""}),"复制真实列数据，排除生成列"));}
    for r in &meta.triggers{if k.is_mysql_family(){require_mysql_trigger_environment(r,&meta.table)?;}let new=generated_name(k,target,get(r,"name")?);steps.push(step(copy_trigger(get(r,"definition")?,b,target,&new)?,"数据完成后安装原始触发器"));if k.is_pg_family(){let mode=match get(r,"enabled")?{"O"=>"ENABLE","D"=>"DISABLE","R"=>"ENABLE REPLICA","A"=>"ENABLE ALWAYS",_=>return Err(anyhow!("TABLE_TRIGGER_ENABLE_UNKNOWN"))};steps.push(step(format!("ALTER TABLE {dest} {mode} TRIGGER {}",name(k,&new)?),"保留触发器启用状态"));if let Some(comment)=opt(r,"comment")?{steps.push(step(format!("COMMENT ON TRIGGER {} ON {dest} IS {}",name(k,&new)?,db::quote_literal(&comment)),"保留触发器注释"));}}}
    Ok(steps)
}
pub(super) async fn restore_sequences(s:&mut Session,b:&Stored,target:&str)->Result<()>{let k=s.kind();if k.is_mysql_family(){let meta=native(b)?;let ts=tokens(&b.ddl)?;for t in ts{if let Some(value)=t.text.to_ascii_uppercase().strip_prefix("AUTO_INCREMENT="){let value:u64=value.parse()?;let dest=db::qualified(&k,&b.public.schema.database,target);s.execute(&format!("ALTER TABLE {dest} AUTO_INCREMENT={value}")).await?;}}let _=meta;return Ok(());}let meta=native(b)?;let dest=db::qualified(&k,&b.public.schema.database,target);for seq in &meta.sequences{let source=db::qualified(&k,get(seq,"schema")?,get(seq,"name")?);let rows=s.rows(&format!("SELECT last_value::text AS value,is_called::text AS called FROM {source}")).await?;ensure!(rows.len()==1,"TABLE_SEQUENCE_STATE_UNKNOWN");let after=s.scalar(&format!("SELECT pg_get_serial_sequence({},{})",db::quote_literal(&dest),db::quote_literal(get(seq,"column")?))).await?;ensure!(after!=source,"TABLE_COPY_SEQUENCE_SHARED");let value=get(&rows[0],"value")?.parse::<i64>()?;let called=get(&rows[0],"called")?;ensure!(["true","false"].contains(&called),"TABLE_SEQUENCE_CALLED_UNKNOWN");s.scalar(&format!("SELECT setval({}::regclass,{value},{called})::text",db::quote_literal(&after))).await?;let actual=s.rows(&format!("SELECT last_value::text AS value,is_called::text AS called FROM {after}")).await?;ensure!(actual==rows,"TABLE_COPY_SEQUENCE_READBACK_MISMATCH");}Ok(())}
pub(super) async fn canonical_checks(s:&mut Session,after:&Stored,d:&mut TableDesign)->Result<()>{
    let Some(checks)=d.checks.as_mut()else{return Ok(())};if checks.is_empty(){return Ok(());}let k=s.kind();let temp=format!("__navkit_check_{}",uuid::Uuid::new_v4().simple());let full=db::qualified(&k,&d.schema,&d.table);let quoted=name(&k,&temp)?;
    s.execute(&format!("CREATE TEMP TABLE {quoted} (LIKE {full} INCLUDING GENERATED)")).await?;
    for c in checks{s.execute(&format!("ALTER TABLE pg_temp.{quoted} ADD CONSTRAINT {} CHECK ({})",name(&k,&c.name)?,c.expression)).await?;let row=s.rows(&format!("SELECT pg_get_constraintdef(oid,false) AS definition FROM pg_constraint WHERE conrelid={}::regclass AND conname={}",db::quote_literal(&format!("pg_temp.{quoted}")),db::quote_literal(&c.name))).await?;ensure!(row.len()==1,"TABLE_CHECK_CANONICAL_DEFINITION_UNKNOWN");c.expression=crate::table_copy::check_expression(get(&row[0],"definition")?)?;}
    s.execute(&format!("DROP TABLE pg_temp.{quoted}")).await?;let _=after;Ok(())
}
pub(super) fn verify_design(before:&Stored,after:&Stored,d:&TableDesign)->Result<()>{ensure!(after.public.schema.columns.iter().map(|c|&c.name).collect::<Vec<_>>()==d.columns.iter().map(|c|&c.name).collect::<Vec<_>>(),"TABLE_COLUMN_ORDER_READBACK_MISMATCH");let mismatches=design::verify(&after.public.schema,d,&before.kind);ensure!(mismatches.is_empty(),"TABLE_NATIVE_DESIGN_READBACK_MISMATCH: {}",mismatches.join("；"));for c in &d.columns{let a=after.public.schema.columns.iter().find(|a|a.name==c.name).ok_or_else(||anyhow!("TABLE_COLUMN_READBACK_MISSING"))?;ensure!(a.comment.as_deref().unwrap_or("")==c.comment.as_deref().unwrap_or(""),"TABLE_COLUMN_COMMENT_READBACK_MISMATCH");}
    let expected=d.checks.as_ref().or(before.public.design.checks.as_ref()).unwrap();let actual=after.public.design.checks.as_ref().unwrap();ensure!(expected.len()==actual.len()&&expected.iter().all(|e|actual.iter().any(|a|a.name==e.name&&normalize(&a.expression)==normalize(&e.expression))),"TABLE_CHECK_READBACK_MISMATCH");
    let wanted=d.triggers.as_ref().or(before.public.design.triggers.as_ref()).unwrap();ensure!(wanted.len()==after.public.objects.triggers.len(),"TABLE_TRIGGER_READBACK_COUNT_MISMATCH");for t in wanted{let actual=after.public.design.triggers.as_ref().unwrap().iter().find(|a|a.name==t.name).ok_or_else(||anyhow!("TABLE_TRIGGER_READBACK_MISSING"))?;ensure!(normalize(&actual.statement)==normalize(&t.statement),"TABLE_TRIGGER_READBACK_DEFINITION_MISMATCH");if before.kind.is_pg_family(){let old=native(before)?;let new=native(after)?;if let Some(previous)=old.triggers.iter().find(|r|get(r,"name").ok()==Some(t.orig_name.as_deref().unwrap_or(&t.name))){let current=new.triggers.iter().find(|r|get(r,"name").ok()==Some(t.name.as_str())).ok_or_else(||anyhow!("TABLE_TRIGGER_READBACK_MISSING"))?;ensure!(get(previous,"enabled")?==get(current,"enabled")?,"TABLE_TRIGGER_ENABLE_READBACK_MISMATCH");}}}
    let expected=options(&before.public.options,d.options.as_ref(),before.kind.is_mysql_family())?;let actual=&after.public.options;for (a,b) in [(&expected.engine,&actual.engine),(&expected.charset,&actual.charset),(&expected.collation,&actual.collation),(&expected.row_format,&actual.row_format)]{ensure!(match(a,b){(Some(a),Some(b))=>a.eq_ignore_ascii_case(b),(None,None)=>true,_=>false},"TABLE_OPTION_READBACK_MISMATCH");}ensure!(expected.fillfactor==actual.fillfactor&&expected.strict==actual.strict&&expected.without_rowid==actual.without_rowid,"TABLE_OPTION_READBACK_MISMATCH");
    // 未修改原始对象应逐条保全，不能只用公共简化模型验证。
    let old=native(before)?;let new=native(after)?;for r in &old.columns{let n=get(r,"name")?;if d.columns.iter().any(|c|c.orig_name.as_deref()==Some(n)&&before.public.design.columns.iter().any(|old|equal(old,c))){let a=new.columns.iter().find(|a|get(a,"name").ok()==Some(n)).ok_or_else(||anyhow!("TABLE_PRESERVED_COLUMN_MISSING"))?;let mut expected=r.clone();expected.remove("ordinal");let mut actual=a.clone();actual.remove("ordinal");ensure!(expected==actual,"TABLE_UNCHANGED_COLUMN_FEATURE_LOST: {n}");}}
    if d.indexes.is_none()||equal(&d.indexes,&before.public.design.indexes){ensure!(old.indexes==new.indexes,"TABLE_UNCHANGED_FULL_INDEX_LOST");}
    if d.foreign_keys.is_none()||equal(&d.foreign_keys,&before.public.design.foreign_keys){let mut a=old.constraints.clone();let mut b=new.constraints.clone();if before.kind.is_pg_family(){a.retain(|r|get(r,"kind").ok()==Some("f"));b.retain(|r|get(r,"kind").ok()==Some("f"));}ensure!(a==b,"TABLE_UNCHANGED_FOREIGN_KEY_FEATURE_LOST");}
    if d.triggers.is_none()||equal(&d.triggers,&before.public.design.triggers){ensure!(old.triggers==new.triggers,"TABLE_UNCHANGED_FULL_TRIGGER_LOST");}
    Ok(())}
fn normalize(s:&str)->String{
    let Ok(mut ts)=tokens(s)else{return s.into()};while ts.first().is_some_and(|t|t.symbol("("))&&ts.last().is_some_and(|t|t.symbol(")")){let mut depth=0;let mut wraps=true;for(i,t)in ts.iter().enumerate(){if t.symbol("("){depth+=1;}if t.symbol(")"){depth-=1;if depth==0&&i+1<ts.len(){wraps=false;break;}}}if !wraps{break;}ts.remove(0);ts.pop();}
    let mut out=String::new();for t in ts{let value=if t.kind==TokenKind::Word{t.text.to_ascii_lowercase()}else if t.kind==TokenKind::Identifier{let id=identifier(&t).unwrap_or_else(|_|t.text.into());if id.bytes().all(|b|b.is_ascii_lowercase()||b.is_ascii_digit()||b==b'_'){id}else{format!("\"{}\"",id.replace('"',"\"\""))}}else{t.text.into()};let word=|c:char|c.is_alphanumeric()||c=='_';if out.chars().last().is_some_and(word)&&value.chars().next().is_some_and(word){out.push(' ');}out.push_str(&value);}out
}
fn mysql_copy_definition_parts(sql:&str)->Result<(Vec<String>,String)>{
    let ts=tokens(sql)?;ensure!(ts.first().is_some_and(|t|t.word("CREATE"))&&ts.get(1).is_some_and(|t|t.word("TABLE")),"TABLE_COPY_MYSQL_HEADER_UNSUPPORTED");
    let (start,end)=qualified_span(sql,&ts,2)?;let open=ts.iter().position(|t|t.symbol("(")).ok_or_else(||anyhow!("TABLE_COPY_MYSQL_HEADER_UNSUPPORTED"))?;
    ensure!(open>2&&ts[open-1].end==end,"TABLE_COPY_MYSQL_HEADER_UNSUPPORTED");
    // 原生计划使用完整 database.table，而 SHOW CREATE 可只返回 table；仅归一化已解析的头部身份，列/约束/选项仍由原解析器完整核验。
    let unqualified=patch(sql,vec![(start,end,"__copy_readback".into())])?;let (_,parts,suffix)=crate::table_copy::table_parts(&unqualified)?;Ok((parts,suffix))
}
pub(super) fn verify_copy(before:&Stored,after:&Stored,target:&str)->Result<()>{
    let old=native(before)?;let new=native(after)?;ensure!(before.public.options==after.public.options&&before.public.schema.comment==after.public.schema.comment,"TABLE_COPY_OPTIONS_COMMENT_MISMATCH");
    ensure!(old.columns.len()==new.columns.len()&&old.indexes.len()==new.indexes.len()&&old.triggers.len()==new.triggers.len(),"TABLE_COPY_OBJECT_COUNT_MISMATCH");
    for (a,b) in old.columns.iter().zip(&new.columns){let mut a=a.clone();let mut b=b.clone();a.remove("ordinal");b.remove("ordinal");if before.kind.is_pg_family()&&get(&a,"auto")?=="1"{a.remove("default");b.remove("default");}ensure!(a==b,"TABLE_COPY_FULL_COLUMN_MISMATCH");}
    if before.kind.is_mysql_family(){
        let expected=operation_steps(before,&workflow::TableOperation{connection_id:String::new(),schema:before.public.schema.database.clone(),table:before.public.schema.table.clone(),kind:"copy_structure".into(),target_table:Some(target.into()),base_revision:String::new(),source_fingerprint:String::new()})?[0].sql.clone();let (a,suffix)=mysql_copy_definition_parts(&expected)?;let (b,actual_suffix)=mysql_copy_definition_parts(&after.ddl)?;ensure!(a.iter().map(|s|normalize(s)).collect::<Vec<_>>()==b.iter().map(|s|normalize(s)).collect::<Vec<_>>(),"TABLE_COPY_MYSQL_FULL_DEFINITION_MISMATCH");ensure!(normalize(&strip_auto(&suffix))==normalize(&strip_auto(&actual_suffix)),"TABLE_COPY_MYSQL_FULL_OPTIONS_MISMATCH");ensure!(auto_increment_value(&suffix)?==auto_increment_value(&actual_suffix)?,"TABLE_COPY_MYSQL_SEQUENCE_READBACK_MISMATCH");
    }else{
        ensure!(old.constraints.len()==new.constraints.len()&&old.sequences.len()==new.sequences.len(),"TABLE_COPY_PG_CONSTRAINT_SEQUENCE_COUNT");
        let mut expected=old.constraints.iter().map(|r|rewrite_reference(get(r,"definition")?,before,target).map(|s|normalize(&s))).collect::<Result<Vec<_>>>()?;let mut actual=new.constraints.iter().map(|r|Ok(normalize(get(r,"definition")?))).collect::<Result<Vec<_>>>()?;expected.sort();actual.sort();ensure!(expected==actual,"TABLE_COPY_PG_CONSTRAINT_DEFINITION_MISMATCH");
        // LIKE 索引名由 PostgreSQL 生成，比较父表 ON 之后的完整定义（含表达式/谓词/INCLUDE/opclass）。
        let shape=|r:&Record|->Result<String>{let def=get(r,"definition")?;let ts=tokens(def)?;let on=ts.iter().position(|t|t.word("ON")).ok_or_else(||anyhow!("TABLE_INDEX_DEFINITION_UNKNOWN"))?;let (_,end)=qualified_span(def,&ts,on+1)?;Ok(format!("{}:{}:{}",get(r,"unique")?,get(r,"primary")?,format!("{}:{}",normalize(&def[end..]),opt(r,"comment")?.unwrap_or_default())))};let mut a=old.indexes.iter().map(shape).collect::<Result<Vec<_>>>()?;let mut b=new.indexes.iter().map(shape).collect::<Result<Vec<_>>>()?;a.sort();b.sort();ensure!(a==b,"TABLE_COPY_PG_FULL_INDEX_MISMATCH");
        for seq in &old.sequences{let new=new.sequences.iter().find(|s|get(s,"column").ok()==get(seq,"column").ok()).ok_or_else(||anyhow!("TABLE_COPY_OWNED_SEQUENCE_MISSING"))?;for field in ["type","start","increment","min","max","cache","cycle","identity"]{ensure!(get(seq,field)?==get(new,field)?,"TABLE_COPY_SEQUENCE_OPTIONS_MISMATCH");}ensure!(get(seq,"name")?!=get(new,"name")?,"TABLE_COPY_SEQUENCE_SHARED");}
    }
    for r in &old.triggers{let new_name=generated_name(&before.kind,target,get(r,"name")?);let actual=new.triggers.iter().find(|a|get(a,"name").ok()==Some(new_name.as_str())).ok_or_else(||anyhow!("TABLE_COPY_TRIGGER_MISSING"))?;let expected=copy_trigger(get(r,"definition")?,before,target,&new_name)?;ensure!(normalize(&expected)==normalize(get(actual,"definition")?),"TABLE_COPY_TRIGGER_DEFINITION_MISMATCH");if before.kind.is_mysql_family(){verify_mysql_trigger_environment(r,actual)?;}if before.kind.is_pg_family(){ensure!(get(r,"enabled")?==get(actual,"enabled")?,"TABLE_COPY_TRIGGER_ENABLE_MISMATCH");ensure!(opt(r,"comment")?==opt(actual,"comment")?,"TABLE_COPY_TRIGGER_COMMENT_MISMATCH");}}
    Ok(())}
fn auto_increment_value(s:&str)->Result<Option<u64>>{let ts=tokens(s)?;for(i,t)in ts.iter().enumerate(){if let Some(n)=t.text.to_ascii_uppercase().strip_prefix("AUTO_INCREMENT="){return Ok(Some(n.parse()?));}if t.word("AUTO_INCREMENT")&&ts.get(i+1).is_some_and(|t|t.text=="="){return Ok(Some(ts.get(i+2).ok_or_else(||anyhow!("TABLE_SEQUENCE_VALUE_UNKNOWN"))?.text.parse()?));}}Ok(None)}
fn strip_auto(s:&str)->String{let Ok(ts)=tokens(s)else{return s.into()};let mut edits=Vec::new();for(i,t)in ts.iter().enumerate(){if t.text.to_ascii_uppercase().starts_with("AUTO_INCREMENT="){edits.push((t.start,t.end,String::new()));}else if t.word("AUTO_INCREMENT"){if let Some(v)=ts.get(i+1){edits.push((t.start,v.end,String::new()));}}}patch(s,edits).unwrap_or_else(|_|s.into())}

