        let b=fixture(false);let mut op=operation();op.kind="clear".into();op.target_table=None;let steps=operation_steps(&b,&op).unwrap();assert_eq!(steps.len(),1);assert_eq!(steps[0].sql,"DELETE FROM \"fixture\".\"src\"");assert!(!steps[0].sql.contains("row_security"));
