    #[test]fn mysql_copy_trigger_environment_is_validated_before_returning_any_plan(){
        let mut b=fixture(true);b.native.as_mut().unwrap().triggers.push(mysql_trigger());let steps=operation_steps(&b,&operation()).unwrap();let data=steps.iter().position(|s|s.sql.starts_with("INSERT INTO")).unwrap();let trigger=steps.iter().position(|s|s.sql.starts_with("CREATE DEFINER")).unwrap();assert!(data<trigger);assert!(steps[trigger].sql.contains("'A'='a'"));
        for (field,value) in [("charset","latin1"),("collation","utf8mb4_bin"),("charset",""),("collation","")]{b.native.as_mut().unwrap().triggers[0]=mysql_trigger();b.native.as_mut().unwrap().triggers[0].insert(field.into(),Some(value.into()));assert!(operation_steps(&b,&operation()).is_err(),"different/empty {field}");}
        for field in ["charset","collation"]{b.native.as_mut().unwrap().triggers[0]=mysql_trigger();b.native.as_mut().unwrap().triggers[0].remove(field);assert!(operation_steps(&b,&operation()).is_err(),"missing {field}");b.native.as_mut().unwrap().triggers[0].insert(field.into(),None);assert!(operation_steps(&b,&operation()).is_err(),"null {field}");}
        b.native.as_mut().unwrap().triggers[0]=mysql_trigger();for field in ["session_charset_client","session_collation_connection"]{let old=b.native.as_mut().unwrap().table.remove(field).unwrap();assert!(operation_steps(&b,&operation()).is_err(),"missing {field}");b.native.as_mut().unwrap().table.insert(field.into(),old);}
    }
    #[test]fn mysql_copy_readback_checks_charset_collation_and_mode_even_when_sql_matches(){
        let mut before=fixture(true);before.native.as_mut().unwrap().triggers.push(mysql_trigger());let target="copied";
        let mut after=fixture(true);after.native=before.native.clone();after.public.schema.table=target.into();after.ddl=operation_steps(&before,&operation()).unwrap()[0].sql.clone();let renamed=generated_name(&before.kind,target,"audit_trigger");let definition=copy_trigger(get(&before.native.as_ref().unwrap().triggers[0],"definition").unwrap(),&before,target,&renamed).unwrap();
        after.native.as_mut().unwrap().triggers[0].insert("name".into(),Some(renamed));after.native.as_mut().unwrap().triggers[0].insert("definition".into(),Some(definition.clone()));verify_copy(&before,&after,target).unwrap();
        // 计划完整名称与真实 SHOW CREATE 无数据库前缀两种头部都必须通过完整读回。
        after.ddl=after.ddl.replacen("CREATE TABLE `fixture`.`copied`","CREATE TABLE `copied`",1);verify_copy(&before,&after,target).unwrap();
        let complete=after.ddl.clone();for (from,to) in [("CHECK(id>0)","CHECK(id>1)"),("REFERENCES `fixture`.`copied`(id)","REFERENCES `fixture`.`src`(id)")]{assert!(complete.contains(from));after.ddl=complete.replacen(from,to,1);assert!(verify_copy(&before,&after,target).unwrap_err().to_string().contains("TABLE_COPY_MYSQL_FULL_DEFINITION_MISMATCH"));}after.ddl=complete;
        for (field,value) in [("charset","latin1"),("collation","utf8mb4_bin"),("mode","STRICT_ALL_TABLES,NO_BACKSLASH_ESCAPES")]{let old=after.native.as_mut().unwrap().triggers[0].insert(field.into(),Some(value.into()));assert_eq!(get(&after.native.as_ref().unwrap().triggers[0],"definition").unwrap(),definition);assert!(verify_copy(&before,&after,target).unwrap_err().to_string().contains("TABLE_COPY_TRIGGER_ENVIRONMENT_READBACK_MISMATCH"),"readback {field}");after.native.as_mut().unwrap().triggers[0].insert(field.into(),old.unwrap());}
        for field in ["charset","collation"]{let old=after.native.as_mut().unwrap().triggers[0].remove(field).unwrap();assert!(verify_copy(&before,&after,target).is_err(),"missing readback {field}");after.native.as_mut().unwrap().triggers[0].insert(field.into(),old);}
        assert!(verify_copy(&before,&after,target).is_ok());
    }
    #[test]fn mysql_trigger_mode_and_backslash_protection_remain_enforced(){
        let mut b=fixture(true);let mut trigger=mysql_trigger();trigger.insert("mode".into(),Some("STRICT_ALL_TABLES,NO_BACKSLASH_ESCAPES".into()));b.native.as_mut().unwrap().triggers.push(trigger);assert!(operation_steps(&b,&operation()).is_err());
        b.native.as_mut().unwrap().triggers[0]=mysql_trigger();b.native.as_mut().unwrap().triggers[0].insert("mode".into(),Some(String::new()));assert!(operation_steps(&b,&operation()).is_ok());b.native.as_mut().unwrap().triggers[0].insert("definition".into(),Some("CREATE TRIGGER audit_trigger AFTER INSERT ON src FOR EACH ROW INSERT INTO audit VALUES('a\\b')".into()));assert!(operation_steps(&b,&operation()).is_err());
    }
